{'base_css': ':root{\n  --ink:#2A1F5C; --muted:#6B5A6E; --accent:#E8457A; --accent-dark:#B42D5E; --butter:#FFC857; --mint:#8FD6BD; --mint-dark:#4E9C84;\n  --paper:#FFF6E6; --paper-line:#EEDCBF;\n  --display:"Caprasimo","Cooper Black",Georgia,serif;\n  --body:"Figtree",system-ui,-apple-system,"Segoe UI",sans-serif;\n  --hand:"Caveat","Segoe Print","Comic Sans MS",cursive;\n  color-scheme:light;\n}\n*,*::before,*::after{box-sizing:border-box}\nhtml,body,button,a{touch-action:manipulation}\nhtml,body{height:100%;margin:0}\nbody{font-family:var(--body);font-size:17px;line-height:1.5;color:var(--ink);background:#1E1A3A;overflow:hidden;-webkit-tap-highlight-color:transparent}\nmain{position:relative;z-index:2;height:100%;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain}\nmain[hidden]{display:none}\n.loader{position:relative;z-index:2;height:100%;display:flex;align-items:center;justify-content:center;text-align:center;padding:24px;font:700 2.2rem var(--hand);color:#FFF1DE}\n\n\n.scene{min-height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:14px;padding:64px 16px 26px}\n.scene[hidden]{display:none}\n.art{position:relative;display:flex;align-items:center;justify-content:center;flex:none}\n.words{width:min(100%,440px);display:flex;flex-direction:column;align-items:center;gap:10px;padding:18px 18px 20px;border-radius:26px;\n  background:rgba(255,248,238,.88);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 10px 30px rgba(20,10,40,.3)}\nh1,h2{font-family:var(--display);font-weight:400;margin:0;line-height:1.05;color:var(--ink)}\nh1{font-size:clamp(2.2rem,9vw,3rem)}\nh2{font-size:clamp(1.6rem,6.6vw,2.1rem)}\nh1:focus,h2:focus,.question:focus{outline:none}\np{margin:0}\n.name{color:var(--accent);font-size:clamp(2.8rem,13vw,4.2rem);overflow-wrap:anywhere}\n.kick{font:700 .8rem var(--body);letter-spacing:.16em;text-transform:uppercase;color:var(--accent-dark)}\n.sub{color:var(--muted);max-width:32ch}\n.whisper{font:700 1.75rem/1.05 var(--hand);color:var(--accent-dark)}\n.whisper:empty{display:none}\n.riddle{font:700 1.6rem/1.1 var(--hand);color:var(--ink);max-width:24ch}\n.count{font-size:.9rem;font-weight:700;color:var(--muted);letter-spacing:.02em}\n.count:empty{display:none}\n.btn{appearance:none;border:0;cursor:pointer;font:700 1.05rem/1 var(--body);color:#fff;background:var(--accent);padding:16px 30px;border-radius:999px;\n  box-shadow:0 5px 0 var(--accent-dark);position:relative;transition:transform .1s,box-shadow .1s;white-space:nowrap;user-select:none;-webkit-user-select:none}\n.btn:active{transform:translateY(4px);box-shadow:0 1px 0 var(--accent-dark)}\n.btn.ghost{background:#fff;color:var(--ink);box-shadow:inset 0 0 0 2px var(--ink)}\n.btn.mint{background:var(--mint-dark);box-shadow:0 5px 0 #2F6E5B}\n.btn:disabled{opacity:.6;cursor:default}\n.btn[hidden]{display:none}\n.linkish{appearance:none;border:0;background:none;font:600 .92rem var(--body);color:var(--accent-dark);text-decoration:underline;cursor:pointer;padding:4px}\n.linkish[hidden]{display:none}\n.plain{appearance:none;border:0;padding:0;background:none;cursor:pointer;display:block}\nimg{-webkit-user-drag:none;user-select:none;-webkit-user-select:none}\n:is(.btn,.linkish,.icon-btn,.plain):focus-visible{outline:3px solid var(--butter);outline-offset:4px}\n.pop-in{animation:popin .5s cubic-bezier(.2,1.5,.4,1) both}\n@keyframes popin{from{transform:scale(.85);opacity:0}}\n.bob{animation:bob 3.2s ease-in-out infinite}\n@keyframes bob{50%{transform:translateY(-8px)}}\n.halo{position:absolute;inset:-8px;border-radius:24px;box-shadow:0 0 0 3px rgba(255,200,87,.9);animation:pulse 1.6s ease-in-out infinite;pointer-events:none}\n.halo.round{border-radius:50%}\n.done>.halo,.halo[hidden]{display:none}\n@keyframes pulse{50%{box-shadow:0 0 0 10px rgba(255,200,87,0)}}\n.dots{position:fixed;top:calc(env(safe-area-inset-top,0px) + 16px);left:50%;transform:translateX(-50%);display:flex;gap:6px;z-index:20}\n.dots[hidden]{display:none}\n.dots span{width:7px;height:7px;border-radius:50%;background:#FFF1DE;opacity:.4;transition:opacity .3s,width .3s}\n.dots span.on{opacity:.95;width:20px;border-radius:4px}\n.icon-btn{position:fixed;top:calc(env(safe-area-inset-top,0px) + 8px);right:10px;z-index:21;width:44px;height:44px;border-radius:50%;border:0;cursor:pointer;\n  background:rgba(255,248,238,.88);color:var(--ink);font-size:1.1rem;box-shadow:0 4px 14px rgba(20,10,40,.25)}\n.icon-btn[hidden]{display:none}\ncanvas#fx{position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:6}\n.made{font-size:.82rem;color:var(--muted)}\n.made a{color:var(--accent-dark);font-weight:700}\n.note{min-height:4.6em;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;width:100%;padding:12px 14px;border-radius:18px;background:var(--paper);box-shadow:inset 0 0 0 2px var(--paper-line)}\n.note[hidden]{display:none}\n.note .tag{font:700 .78rem var(--body);letter-spacing:.08em;text-transform:uppercase;color:var(--accent-dark)}\n.note .tag:empty{display:none}\n.note .big{font:700 1.65rem/1.1 var(--hand);color:var(--ink)}\n.note .hint{font-size:.9rem;color:var(--muted)}\n.note .hint:empty{display:none}\n.paper{width:100%;text-align:left;display:flex;flex-direction:column;gap:6px;padding:14px 16px;border-radius:6px;background:repeating-linear-gradient(180deg,#FFF9EE 0 33px,#EADCC4 33px 34px);\n  box-shadow:0 6px 16px rgba(40,10,30,.18);max-height:min(40dvh,360px);overflow-y:auto;transform:rotate(-1deg)}\n.paper p{font:600 1.5rem/1.15 var(--hand);color:var(--ink);opacity:0;transform:translateY(4px);transition:opacity .9s,transform .9s}\n.paper p.in{opacity:1;transform:none}\n.paper p.sign{text-align:right;color:var(--accent-dark)}\n.paper[hidden]{display:none}\n.drop{filter:drop-shadow(0 14px 18px rgba(20,8,30,.4))}\n', 'load_js': 'function waitForPreviewData(){\n  return new Promise(res => {\n    addEventListener("message", e => { if (e.origin === location.origin && e.data && e.data.type === "lg-data") res(e.data.data); });\n    parent.postMessage({ type: "lg-ready" }, location.origin);\n  });\n}\nfunction addWatermark(){\n  const svg = "<svg xmlns=\'http://www.w3.org/2000/svg\' width=\'280\' height=\'180\'><text x=\'10\' y=\'105\' transform=\'rotate(-25 140 90)\' font-family=\'Arial,sans-serif\' font-weight=\'700\' font-size=\'22\' fill=\'rgba(255,241,222,0.38)\'>PREVIEW · Little Gasp</text></svg>";\n  const wm = document.createElement("div"); wm.setAttribute("aria-hidden", "true");\n  wm.style.cssText = "position:fixed;inset:0;pointer-events:none;z-index:50;background-image:url(\\"data:image/svg+xml," + encodeURIComponent(svg) + "\\")";\n  const band = document.createElement("div"); band.textContent = "PREVIEW · Unlock to remove watermark";\n  band.style.cssText = "position:fixed;left:0;right:0;bottom:0;z-index:51;pointer-events:none;background:rgba(42,31,92,.9);color:#fff;font:700 13px/1 Figtree,system-ui,sans-serif;text-align:center;padding:9px 6px;letter-spacing:.04em";\n  document.body.append(wm, band);\n}\n', 'helpers': 'function dragOrTap(el, fn, test){\n  let p0 = null, fired = false;\n  const fire = () => { if (!fired){ fired = true; fn(); } };\n  el.addEventListener("pointerdown", e => { p0 = [e.clientX, e.clientY]; el.setPointerCapture && el.setPointerCapture(e.pointerId); });\n  el.addEventListener("pointermove", e => { if (p0 && test(e.clientX - p0[0], e.clientY - p0[1])){ p0 = null; fire(); } });\n  el.addEventListener("pointerup", e => { if (p0 && Math.hypot(e.clientX - p0[0], e.clientY - p0[1]) < 10) fire(); p0 = null; });\n  el.addEventListener("pointercancel", () => p0 = null);\n  el.addEventListener("click", e => { if (e.detail === 0) fire(); });   // keyboard Enter / Space\n  return { reset(){ fired = false; }, fire };\n}\nfunction writeLines(box, lines, signIdx){\n  box.innerHTML = lines.map((l, i) => `<p${i === signIdx ? \' class="sign"\' : ""}></p>`).join("");\n  $$(`#${box.id} p`).forEach((p, i) => p.textContent = lines[i]);\n}\nasync function revealLines(box, ok){\n  for (const p of box.querySelectorAll("p")){ if (!ok()) break; p.classList.add("in"); if (ctx) noise(.2, 3800, .02, .6);\n    if (!isAuto) p.scrollIntoView({ block: "nearest", behavior: reduce ? "auto" : "smooth" }); await sleep(reduce ? 0 : Math.min(2600, 700 + p.textContent.length * 24)); }\n  box.querySelectorAll("p").forEach(p => p.classList.add("in"));\n}\n\n', 'sound': '/* ---------- sound: the buyer\'s song, or our own music-box tune ---------- */\nlet ctx, master, muted = false, song = null, musicOn = false, unlocked = false;\nfunction ensureAudio(){\n  if (isAuto) return;\n  const AC = window.AudioContext || window.webkitAudioContext; if (!AC) return;\n  if (!ctx){ ctx = new AC(); master = ctx.createGain(); master.gain.value = muted ? 0 : .5; master.connect(ctx.destination); }\n  if (ctx.state === "suspended") ctx.resume();\n}\nfunction unlockSong(){\n  if (unlocked || !song) return; unlocked = true;\n  song.muted = true; song.play().then(() => { if (!musicOn){ song.pause(); song.currentTime = 0; } song.muted = muted; }).catch(() => {});\n}\nfunction startMusic(){\n  if (isAuto || musicOn) return; musicOn = true; ensureAudio();\n  if (song){ song.muted = muted; song.currentTime = 0; song.play().catch(() => { song = null; Music.start(); }); }\n  else Music.start();\n  $("#muteBtn").hidden = false;\n}\nfunction bell(f, t, vol = .12, len = 1.6){   // music-box / celesta voice\n  if (!ctx) return;\n  [[1, vol, "sine"], [2.01, vol * .32, "sine"], [3.98, vol * .12, "sine"], [1, vol * .25, "triangle"]].forEach(([m, v, ty]) => { const o = ctx.createOscillator(), g = ctx.createGain();\n    o.type = ty; o.frequency.value = f * m; g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(v, t + .005);\n    g.gain.exponentialRampToValueAtTime(0.0001, t + len / Math.sqrt(m)); o.connect(g); g.connect(master); o.start(t); o.stop(t + len / Math.sqrt(m) + .05); });\n}\nfunction pad(fs, t, len, vol = .028){\n  if (!ctx) return;\n  fs.forEach(f => { const o = ctx.createOscillator(), g = ctx.createGain(), fl = ctx.createBiquadFilter();\n    o.type = "triangle"; o.frequency.value = f; fl.type = "lowpass"; fl.frequency.value = 900;\n    g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(vol, t + .6); g.gain.linearRampToValueAtTime(0.0001, t + len);\n    o.connect(fl); fl.connect(g); g.connect(master); o.start(t); o.stop(t + len + .05); });\n}\nfunction noise(len = .2, f = 2000, vol = .12, q = 1, type = "bandpass"){\n  if (!ctx) return; const n = Math.floor(ctx.sampleRate * len), b = ctx.createBuffer(1, n, ctx.sampleRate), a = b.getChannelData(0);\n  for (let i = 0; i < n; i++) a[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / n, 2);\n  const s = ctx.createBufferSource(), fl = ctx.createBiquadFilter(), g = ctx.createGain();\n  s.buffer = b; fl.type = type; fl.frequency.value = f; fl.Q.value = q; g.gain.value = vol; s.connect(fl); fl.connect(g); g.connect(master); s.start();\n}\nconst hz = m => 440 * Math.pow(2, (m - 69) / 12);\n/* our own tender tune in D major, 4/4 at 76 bpm, over a I–V–vi–iii–IV–I–IV–V walk: [midi, beat] per bar */\nconst TUNE = [\n  [[78,0],[76,1],[74,1.5],[73,2],[74,3]], [[73,0],[71,1],[69,2],[73,3]],\n  [[71,0],[73,.5],[74,1],[78,2],[76,3]], [[73,0],[69,1],[66,2],[69,3]],\n  [[67,0],[71,1],[74,2],[76,2.5],[74,3]], [[74,0],[78,1],[81,2],[78,3]],\n  [[79,0],[78,1],[76,1.5],[74,2],[71,3]], [[73,0],[74,1],[76,2],[73,3]] ];\nconst CHORD = [[50,54,57],[45,49,52],[47,50,54],[42,45,49],[43,47,50],[50,54,57],[43,47,50],[45,49,52]];\nconst Music = { on:false, bar:0, next:0, timer:null,\n  start(){ if (!ctx || this.on) return; this.on = true; this.bar = 0; this.next = ctx.currentTime + .15; this.tick(); this.timer = setInterval(() => this.tick(), 150); },\n  tick(){ const beat = 60 / 76; while (this.next < ctx.currentTime + .8){ this.play(this.next, this.bar, beat); this.next += 4 * beat; this.bar++; } },\n  play(t, i, beat){\n    const k = i % TUNE.length, ch = CHORD[k];\n    pad(ch.map(m => hz(m)), t, 4 * beat + .3);\n    [0, 1, 2, 3, 2, 1, 0, 1].forEach((j, s) => bell(hz(ch[j % 3] + 12), t + s * beat / 2, .035, 1));   // soft broken chord\n    if (i < 1) return;\n    TUNE[k].forEach(([m, at]) => bell(hz(m), t + at * beat, .1, 1.8));\n  }\n};\nfunction ding(f, d = 0, v = .12){ if (ctx) bell(f, ctx.currentTime + d, v, 1.4); }\nconst chimeUp = () => [1175, 1480, 1760, 2349].forEach((f, i) => ding(f, i * .1, .1));\nfunction dingDong(){ if (!ctx) return; const t = ctx.currentTime; bell(659, t, .22, 2.2); bell(523, t + .55, .22, 2.6); }\nfunction click(){ noise(.05, 2600, .25, 3); noise(.04, 900, .18, 2); }\n$("#muteBtn").addEventListener("click", e => {\n  muted = !muted; if (master) master.gain.value = muted ? 0 : .5; if (song) song.muted = muted;\n  e.currentTarget.setAttribute("aria-pressed", muted); e.currentTarget.setAttribute("aria-label", muted ? "Unmute music" : "Mute music");\n  e.currentTarget.textContent = muted ? "✕" : "♪";\n});\n\n', 'fx': '/* ---------- confetti, hearts, sparkles ---------- */\nconst fx = $("#fx"), fg = fx.getContext("2d");\nlet parts = [], running = false, rain = false;\nfunction sizeFx(){ const r = devicePixelRatio || 1; fx.width = innerWidth * r; fx.height = innerHeight * r; fg.setTransform(r, 0, 0, r, 0, 0); }\nsizeFx(); addEventListener("resize", sizeFx);\nconst CONF = ["#E8457A","#FFC857","#8FD6BD","#FFFFFF","#F08A5D","#2A1F5C"];\nfunction confetti(on){ rain = on && !reduce; run(); }\nfunction hearts(n){\n  if (reduce) return;\n  for (let i = 0; i < n; i++) parts.push({ x: Math.random() * innerWidth, y: innerHeight + 20 + Math.random() * innerHeight * .4, vx: (Math.random() - .5) * .8, vy: -(1.4 + Math.random() * 2.2),\n    s: 7 + Math.random() * 9, c: ["#E8457A","#F49AB6","#FFC857","#B42D5E","#FFFFFF"][i % 5], w: Math.random() * 6, heart: true, life: 400 });\n  run();\n}\nfunction sparkleXY(x, y){\n  if (reduce) return;\n  for (let i = 0; i < 46; i++){ const a = Math.random() * Math.PI * 2, v = 1.5 + Math.random() * 4.5;\n    parts.push({ x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 1, g: .08, s: 2 + Math.random() * 3, c: ["#FFE7A8","#FFC857","#FFF6DC"][i % 3], w: 0, life: 60 + Math.random() * 30 }); }\n  run();\n}\nfunction sparkleAt(el){\n  if (reduce) return; const r = el.getBoundingClientRect(), x = r.left + r.width / 2, y = r.top + r.height / 2;\n  for (let i = 0; i < 46; i++){ const a = Math.random() * Math.PI * 2, v = 1.5 + Math.random() * 4.5;\n    parts.push({ x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 1, g: .08, s: 2 + Math.random() * 3, c: ["#FFE7A8","#FFC857","#FFF6DC"][i % 3], w: 0, life: 60 + Math.random() * 30 }); }\n  run();\n}\nfunction run(){ if (!running){ running = true; requestAnimationFrame(loop); } }\nfunction heartPath(s){ fg.beginPath(); fg.moveTo(0, s * .3); fg.bezierCurveTo(-s, -s * .4, -s * .5, -s * 1.1, 0, -s * .45); fg.bezierCurveTo(s * .5, -s * 1.1, s, -s * .4, 0, s * .3); fg.fill(); }\nfunction loop(){\n  fg.clearRect(0, 0, innerWidth, innerHeight);\n  if (rain && Math.random() < .35) parts.push({ x: Math.random() * innerWidth, y: -20, vx: (Math.random() - .5) * 1.2, vy: 1.2 + Math.random() * 1.4, s: 4 + Math.random() * 4, c: CONF[Math.floor(Math.random() * 6)], w: Math.random() * 6, spin: .1 + Math.random() * .1, rect: true, life: 900 });\n  parts.forEach(p => { p.w += p.spin || .04;\n    p.x += p.vx + (p.heart ? Math.sin(p.w) * .5 : p.rect ? Math.sin(p.w) * .8 : 0); p.y += p.vy; if (p.g) p.vy += p.g; p.life--;\n    fg.save(); fg.translate(p.x, p.y); fg.fillStyle = p.c; fg.globalAlpha = Math.min(1, p.life / 40);\n    if (p.heart) heartPath(p.s);\n    else if (p.rect){ fg.rotate(p.w); fg.scale(1, Math.abs(Math.sin(p.w * 2)) * .8 + .2); fg.fillRect(-p.s / 2, -p.s / 3, p.s, p.s * .66); }\n    else { fg.beginPath(); fg.arc(0, 0, p.s, 0, 7); fg.fill(); } fg.restore(); });\n  parts = parts.filter(p => p.life > 0 && p.y > -80 && p.y < innerHeight + 200);\n  if (parts.length || rain) requestAnimationFrame(loop); else { running = false; fg.clearRect(0, 0, innerWidth, innerHeight); }\n}\n\n', 'reply': 'function reply(kind, text){   // only real, paid links send anything\n  if (!id || isPreview || isAuto) return Promise.resolve(true);\n  return fetch(API_URL, { method: "POST", body: JSON.stringify({ action: "reply", id, kind, text }) })\n    .then(r => r.json()).then(j => !!(j && j.ok)).catch(() => false);\n}\n\n'}